create extension if not exists pgcrypto;
create schema if not exists auth;
create table auth.users(id uuid primary key,email text,raw_user_meta_data jsonb not null default '{}'::jsonb);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text,role text not null default 'user',created_at timestamptz not null default now(),email text not null,full_name text);
create table public.organizations(id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references public.profiles(id) on delete restrict,name text not null check(char_length(trim(name)) between 1 and 160),status text not null default 'active' check(status in('active','suspended')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.organization_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,unit_id uuid,position_title text,status text not null default 'active' check(status in('active','suspended','left')),is_owner boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.licenses(user_id uuid primary key references public.profiles(id) on delete cascade,plan text not null check(plan in('trial','monthly','three_months','annual','lifetime')),status text not null check(status in('trial','active','cancelled')),starts_at date not null default current_date,ends_at date not null,updated_at timestamptz not null default now(),max_companies integer not null default 1 check(max_companies between 1 and 1000),modules text[] not null default array['full_suite']::text[],organization_id uuid not null references public.organizations(id) on delete restrict,max_users integer not null default 1 check(max_users between 1 and 100000),limits jsonb not null default '{}'::jsonb check(jsonb_typeof(limits)='object'));
create unique index licenses_organization_uq on public.licenses(organization_id);
